package art.pikoos.lab.core;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;

/** Original starting content, generated by the same ordinary-Lua model as Blank. */
public final class StarterGames {
    private StarterGames(){}
    public static WorkshopCartridge create(boolean puzzle){
        WorkshopCartridge cart=new WorkshopCartridge(("pico-8 cartridge // http://www.pico-8.com\nversion 43\n__lua__\nfunction _draw()\n cls(1)\nend\n").getBytes(StandardCharsets.ISO_8859_1));
        int[] pixels=new int[16384];Arrays.fill(pixels,-1);
        // Original pixel art: 16x16 elements and one 8x8 scenery tile.
        sprite(pixels,1,new String[]{"00088000","008ee800","08eeee80","8ee77ee8","8ee11ee8","08eeee80","00888800","00800800"});
        sprite(pixels,2,new String[]{"000aa000","000aa000","0aaaaaa0","aa7777aa","0aaaaaa0","00aaaa00","0aa00aa0","00000000"});
        sprite(pixels,3,new String[]{"00555500","05dddd50","5d1111d5","5d1661d5","5d1661d5","5d1111d5","05dddd50","00555500"});
        sprite(pixels,4,new String[]{"00aaaa00","0a7777a0","a77aa77a","a7aaaa7a","a7aaaa7a","a77aa77a","0a7777a0","00aaaa00"});
        sprite(pixels,5,new String[]{"00000000","00bb0000","0bbbb000","00bb0000","00000000","00000b00","0000bbb0","00000b00"});
        cart=cart.withSheetPixels(pixels);
        PlayModel model=new PlayModel();model.background=puzzle?1:3;model.goal=puzzle?2:1;model.winSound=9;
        if(puzzle){
            for(int n=0;n<3;n++){PlayModel.Element e=element(3,32+n*28,60);e.rule=4;e.neighbor=n<2?n+1:-1;e.sound=8;
                e.animation=new PlayAnimation(region(3));e.animation.mode=2;e.animation.frames.get(0).ticks=1;
                e.animation.frames.add(new PlayAnimation.Frame(region(4),30));model.elements.add(e);}
        }else{
            PlayModel.Element walker=element(1,20,60);walker.movement=1;walker.speed=2;model.elements.add(walker);
            for(int[] pos:new int[][]{{52,36},{92,60},{60,92}}){PlayModel.Element star=element(2,pos[0],pos[1]);star.rule=1;star.target=0;star.sound=8;model.elements.add(star);}
            model.world=new PlayWorld();int[] cells=new int[8192];Arrays.fill(cells,-1);for(int y=2;y<15;y++)for(int x=0;x<16;x++)if((x*3+y*5)%11==0)cells[y*128+x]=64;cart=cart.withMapCells(cells);
        }
        // Short, non-looping effects on the existing event channel; never play on creation.
        for(int slot=8;slot<=9;slot++){P8Sfx.Sound sound=new P8Sfx.Sound();sound.speed=8;sound.loopStart=slot==8?2:4;
            for(int n=0;n<sound.loopStart;n++)sound.notes[n]=new int[]{(slot==8?36:40)+n*4,0,4,5};cart=cart.withSound(slot,sound);}
        cart=model.write(cart);GameElementNames names=GameElementNames.empty(model.elements.size());
        for(int n=0;n<names.values.size();n++)names.values.set(n,puzzle?"Lamp "+(n+1):n==0?"Explorer":"Star "+n);
        return names.apply(cart);
    }
    private static PlayModel.Element element(int tile,int x,int y){PlayModel.Element e=new PlayModel.Element();SpriteRegion r=region(tile);e.sx=r.x;e.sy=r.y;e.w=r.width;e.h=r.height;e.x=x;e.y=y;return e;}
    private static SpriteRegion region(int tile){return tile==5?new SpriteRegion(0,32,8,8):new SpriteRegion(8+(tile-1)*16,0,16,16);}
    private static void sprite(int[] pixels,int tile,String[] rows){SpriteRegion r=region(tile);int scale=r.width/8;for(int y=0;y<r.height;y++)for(int x=0;x<r.width;x++)pixels[(r.y+y)*128+r.x+x]=Character.digit(rows[y/scale].charAt(x/scale),16);}
}
